variables.body:
return {
    property: "LegalName", // Default column to search
    operation: "contains", // Default operator
    label: "Legal Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Id",
    "LegalName",
    "TradeName",
    "Active",
    "Email",
    "Phone"
];

const displayColumnOptions = {
    valueKey: {
        "Email": "PrimaryContactEmail",
        "Phone": "PrimaryContactPhone"
    },
    type: {
        "Active": "boolean"
    }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
}

return [
    // --- Identifiers ---
    {
        label: "ID",
        value: "Id",
        type: "number",
        // operators: ["eq"] // IDs usually only support exact match
    },

    // --- Core Identity ---
    {
        label: "Legal Name",
        value: "LegalName",
        type: "string",
        // operators: ["contains", "eq", "startswith", "endswith"]
    },
    {
        label: "Trade Name",
        value: "TradeName",
        type: "string",
        // operators: ["contains", "eq", "startswith", "endswith"]
    },
    {
        label: "Active",
        value: "Active",
        type: "boolean",
        operators: ["eq"] // True/False
    },

    // --- Contact & Location ---
    {
        label: "Address",
        value: "PrimaryAddressLocation",
        type: "string",
        // operators: ["contains"]
    },
    {
        label: "Email",
        value: "PrimaryContactEmail",
        type: "string",
        // operators: ["contains", "eq", "startswith"]
    },
    {
        label: "Phone",
        value: "PrimaryContactPhone",
        type: "string",
        // operators: ["contains", "eq"]
    },
    {
        label: "Website (URL)",
        value: "PrimaryContactUrl",
        type: "string",
        // operators: ["contains"]
    },

    // --- Geographic References (Dropdowns) ---
    // Note: 'source' keys match the map variables
    {
        label: "Country",
        value: "CountryId",
        type: "dropdown",
        source: "countryMap",
        operators: ["eq"]
    },
    {
        label: "State",
        value: "StateId",
        type: "dropdown",
        source: "stateMap",
        operators: ["eq"]
    },
    {
        label: "Fiscal Year Start",
        value: "FiscalYearStart",
        type: "string",
        placeholder: "MM-DD",
        // operators: ["eq"]
    },
    {
        label: "Fiscal Year End",
        value: "FiscalYearEnd",
        type: "string",
        placeholder: "MM-DD",
        // operators: ["eq"]
    }
];
